Object.assign(TH,STORY_TH);
for(const [key,value] of Object.entries({...TH})) if(/^[A-Z][a-z]+$/.test(key))TH[key.toUpperCase()]??=value;
const patterns = [
 [/^Anchored for (.+) · (\d+) nm$/,(_,place,n)=>`ทอดสมอระหว่างทางไป${thai(place)} · ${n} ไมล์ทะเล`],
 [/^About ([\d.]+) days · ([\d.]+) provisions · (\d+) min at this pace$/,(_,days,food,minutes)=>`ประมาณ ${days} วัน · เสบียง ${food} หน่วย · ${minutes} นาทีที่ความเร็วนี้`],
 [/^Returned to Inês\. (.+) joined The Wayfarer\. Received (\d+) gold\.$/,(_,person,n)=>`กลับไปหาอิเนสแล้ว ${thai(person)}ร่วมเรือเดอะเวย์แฟเรอร์ รับ ${n} ทอง`],
 [/^The old chart rests beneath the open sky\. (.+)$/,(_,objective)=>`แผนที่เก่าพักอยู่ใต้ท้องฟ้าเปิด ${thai(objective)}`],
 [/^Day (\d+) · (.+)$/,(_,d,time)=>`วันที่ ${d} · ${time}`],
 [/^(\d+)% hull$/,(_,n)=>`ตัวเรือ ${n}%`],
 [/^Hull integrity: (\d+)%$/,(_,n)=>`ความทนทานตัวเรือ: ${n}%`],
 [/^Hold: (\d+) \/ 40 crates$/,(_,n)=>`ระวาง: ${n} / 40 ลัง`],
 [/^(\d+) \/ 40 crates( loaded)?$/,(_,n)=>`${n} / 40 ลัง`],
 [/^(\d+) (crates|in hold)$/,(_,n,type)=>type==='crates'?`${n} ลัง`:`ในระวาง ${n}`],
 [/^([\d,]+) gold$/,(_,n)=>`${n} ทอง`],
 [/^Delivered: (\d+) \/ 3 crates$/,(_,n)=>`ส่งแล้ว: ${n} / 3 ลัง`],
 [/^Sailing to (.+) · (\d+) nm$/,(_,place,n)=>`กำลังไป${thai(place)} · ${n} ไมล์ทะเล`],
 [/^Set course for (.+)$/,(_,place)=>`กำหนดเส้นทางไป${thai(place)}`],
 [/^Course set for (.+)\.$/,(_,place)=>`กำหนดเส้นทางไป${thai(place)}แล้ว`],
 [/^Arrived at (.+)\.$/,(_,place)=>`ถึง${thai(place)}แล้ว`],
 [/^(Bought|Sold) (.+) for (\d+) gold\.$/,(_,side,good,n)=>`${side==='Bought'?'ซื้อ':'ขาย'}${thai(good)} ${n} ทอง`],
 [/^Trade at (.+)\. Coastal arrivals are simplified for the world chart; prices are part of the game economy\.$/,(_,place)=>`ค้าขายที่${thai(place)} จุดเข้าท่าเรือปรับให้ง่ายสำหรับแผนที่โลก ราคาเป็นส่วนหนึ่งของเศรษฐกิจในเกม`],
 [/^(.+?)(?: ·)? Harbor Quarter$/,(_,place)=>`ย่านท่าเรือ${thai(place)}`],
 [/^Talk to (.+)$/,(_,person)=>`พูดคุยกับ${thai(person)}`],
 [/^Portrait of (.+)$/,(_,person)=>`ภาพเหมือน${thai(person)}`],
 [/^Companion: (.+)$/,(_,person)=>`สหาย: ${thai(person)}`],
 [/^Keepsakes: (.+)$/,(_,items)=>`ของที่ระลึก: ${thai(items)}`],
 [/^Direct hit! Corsair hull: (\d+)%\.$/,(_,n)=>`ยิงเข้าเป้า! ตัวเรือโจรสลัด: ${n}%`],
 [/^Day (\d+) — Arrived at (.+)\.$/,(_,n,place)=>`วันที่ ${n} — ถึง${thai(place)}`]
];
export function thai(text){
 if(TH[text])return TH[text];
 for(const [pattern,format] of patterns)if(pattern.test(text))return text.replace(pattern,format);
 if(text.includes(' · '))return text.split(' · ').map(thai).join(' · ');
 const decorated=text.match(/^([^\p{L}\p{N}]*)([\s\S]+?)(\s*[↗]?)$/u);
 if(decorated&&(decorated[1]||decorated[3])){const translated=thai(decorated[2]);return decorated[1]+translated+decorated[3];}
 return text;
}
export function translateVoyage(text,language='en'){if(language!=='th')return text;const m=text.match(/^(\s*)([\s\S]*?)(\s*)$/);return m[1]+thai(m[2])+m[3];}
export function readLanguage(storage){try{return storage.getItem('narai-language')==='th'?'th':'en';}catch{return'en';}}
export function writeLanguage(storage,language){try{storage.setItem('narai-language',language);return true;}catch{return false;}}
export function localizedValue(current,previous,language){const source=previous&&current===previous.output?previous.source:current;return{source,output:translateVoyage(source,language)};}
export function createVoyageLocale(storage){
 let language=readLanguage(storage);const originals=new WeakMap();
 function render(root=document.body){
  document.documentElement.lang=language;document.title=language==='th'?'นารายณ์ · สายลมแห่งสยาม':'NARAI · Winds of Siam';
  const nodes=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
  while(node=nodes.nextNode()){
   if(!node.parentElement||node.parentElement.closest('script,style,option,.language-switch'))continue;
   const value=localizedValue(node.nodeValue,originals.get(node),language);originals.set(node,value);if(node.nodeValue!==value.output)node.nodeValue=value.output;
  }
  for(const el of root.querySelectorAll('[aria-label],[title]')){
   if(el.matches('.language-switch'))continue;
   const saved=originals.get(el)||{};
   for(const attr of['aria-label','title'])if(el.hasAttribute(attr)){const value=localizedValue(el.getAttribute(attr),saved[attr],language);saved[attr]=value;if(el.getAttribute(attr)!==value.output)el.setAttribute(attr,value.output);}
   originals.set(el,saved);
  }
  for(const button of document.querySelectorAll('.language-switch')){button.textContent=language==='th'?'ไทย / EN':'EN / ไทย';button.setAttribute('aria-label',language==='th'?'เปลี่ยนเป็นภาษาอังกฤษ':'Switch to Thai');}
 }
 document.addEventListener('click',e=>{if(!e.target.closest('.language-switch'))return;language=language==='th'?'en':'th';writeLanguage(storage,language);render();});
 return{render,t:text=>translateVoyage(text,language),get language(){return language;}};
}
